from math import log2

def debug_matrix(a):
	for row in a:
		print(row)
	print()

def debug_list(a):
	print(a)
	print()
t = int(input())
for _ in range(t):
	n = int(input())
	a = list(map(int, input().split()))
	b = list(map(int, input().split()))
	x = [0] * 21
	y = [0] * 21
	cx = [0] * 21
	cy = [0] * 21
	result = [0] * 21
	zx = 0
	zy = 0
	for i in range(21):
		x[i] = [0] * 21
		y[i] = [0] * 21
	for num in a:
		if num == 0:
			zx += 1
			continue
		row = int(log2(num))
		cx[row] += 1
		col = 0
		while num > 0:
			if num & 1:
				x[row][col] += 1
			col += 1
			num >>= 1
	for num in b:
		if num == 0:
			zy += 1
			continue
		row = int(log2(num))
		cy[row] += 1
		col = 0
		while num > 0:
			if num % 2 == 1:
				y[row][col] += 1
			col += 1
			num >>= 1
	for i in range(21):
		if cx[i] == 0:
			continue
		for j in range(21):
			if cy[j] == 0:
				continue
			if i == j:
				for k in range(21):
					result[k] += x[i][k] * y[j][k]
			else:
				for k in range(21):
					result[k] += (cx[i] - x[i][k]) * y[j][k]
					result[k] += (cy[j] - y[j][k]) * x[i][k]
	val = 0
	pow = 1
	for i in result:
		val += pow * i
		pow <<= 1
	if zx > 0:
		val += sum(b) * zx
	if zy > 0:
		val += sum(a) * zy
	print(val)
